-- Informatics: the subject comes back, with the Kazakhstan Republican
-- olympiad archive — regional (oblast) and final (republican) stages, grades
-- 9-11 — from matol.kz.
--
-- Generated from the matol.kz pages; do not edit by hand. Statements keep
-- LaTeX in $ $ and the input/output samples as ``` blocks. 18 problems
-- whose statements need a picture are left out until the figures are added.
-- Topics are assigned by keywords in the statement, as a first sort.
-- Difficulty: the stage's level, plus one for the later half of a paper.
--
-- Licence: recorded as 'unknown'; confirm the terms before publishing.

alter table public.subjects drop constraint if exists subjects_supported_slug;
alter table public.subjects
  add constraint subjects_supported_slug check (slug in ('mathematics', 'physics', 'informatics'));
alter table public.profiles drop constraint if exists profiles_supported_primary_subject;
alter table public.profiles
  add constraint profiles_supported_primary_subject
  check (primary_subject is null or primary_subject in ('Mathematics', 'Physics', 'Informatics'));

insert into public.subjects (name, slug)
select 'Informatics', 'informatics'
where not exists (select 1 from public.subjects where slug = 'informatics');

insert into public.topics (subject_id, name, slug)
select s.id, v.name, v.slug
from (values
  ('Implementation', 'implementation'),
  ('Mathematics and number theory', 'number-theory'),
  ('Greedy and sorting', 'greedy-sorting'),
  ('Dynamic programming', 'dynamic-programming'),
  ('Graphs and trees', 'graphs'),
  ('Strings', 'strings'),
  ('Data structures and queries', 'data-structures'),
  ('Geometry', 'geometry')
) as v(name, slug)
join public.subjects s on s.slug = 'informatics'
on conflict (subject_id, slug) do nothing;

insert into public.tasks (id, subject_id, topic_id, title, problem, difficulty, estimated_minutes, source, source_url, licence, attribution, grade_min, grade_max, paper)
select v.id, s.id, t.id, v.title, v.problem, v.difficulty, v.minutes, v.source, v.source_url, 'unknown',
       'Республиканская олимпиада по информатике, matol.kz', v.gmin, v.gmax, v.paper
